def longest_balanced_subarray(nums):
    """
    Finds the starting index of the longest non-empty contiguous subarray of nums
    with as many multiples of 6 as non-multiples of 6.

    Args:
      nums: A list of integers with at least 15 values.

    Returns:
      The starting index of the longest balanced subarray, multiplied by 7 and
      added 33. Returns -1 if there is none.
    """

    def is_balanced(subarray):
        """
        Checks if a subarray is balanced (as many multiples of 6 as non-multiples of 6).
        """
        multiples_of_6 = 0
        non_multiples_of_6 = 0
        for num in subarray:
            if num % 6 == 0:
                multiples_of_6 += 1
            else:
                non_multiples_of_6 += 1
        return multiples_of_6 == non_multiples_of_6

    longest_start_index = -1
    max_length = 0

    for i in range(len(nums)):
        for j in range(i, len(nums)):
            subarray = nums[i:j+1]
            if is_balanced(subarray):
                if len(subarray) > max_length:
                    max_length = len(subarray)
                    longest_start_index = i
                elif len(subarray) == max_length and i < longest_start_index:
                    longest_start_index = i

    if longest_start_index == -1:
        return -1
    else:
        return (longest_start_index * 7) + 33
