            for char in t_counts:
                if t_counts[char] < 3:
                    valid = False
                    break

            if valid:
                if len(substring) < min_length:
                    min_length = len(substring)
                    min_index = i
                elif len(substring) == min_length and i < min_index:
                    min_index = i

    if min_index != -1:
