def shortest_cover(s, t):
    """
    Finds the starting index of the shortest substring of s that contains each character of t at least 3 times.

    Args:
        s: A non-empty string.
        t: A string.

    Returns:
        The starting index of the shortest substring of s that contains each character of t at least 3 times,
        or -1 if there is none.
    """

    changed_s = ""
    for i in range(len(s)):
        if i % 3 == 0:
            changed_s += s[i]

    if not changed_s:
        return -1

    t_counts = {}
    for char in t:
        t_counts[char] = t_counts.get(char, 0) + 1

    min_len = float('inf')
    result_index = -1

    for i in range(len(changed_s) - len(t) + 1):
        substring = changed_s[i:i + len(t)]
        substring_counts = {}
        for char in substring:
            substring_counts[char] = substring_counts.get(char, 0) + 1

        valid = True
        for char, count in t_counts.items():
            if char not in substring_counts or substring_counts[char] < count:
                valid = False
                break

        if valid:
            if len(substring) < min_len:
                min_len = len(substring)
                result_index = i

    if result_index == -1:
        return -1
    else:
        return result_index + 53
